// WordPressPackages has Core version, plugins and themes.
type WordPressPackages []WpPackage

// CoreVersion returns the core version of the installed WordPress
func (w WordPressPackages) CoreVersion() string {
	for _, p := range w {
		if p.Type == WPCore {
			return p.Version
		}
	}
	return ""
}

